package com.complaint.management;

import jakarta.annotation.PostConstruct;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.client.RestClient;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.stream.Collectors;

@RestController @RequestMapping("/api") @CrossOrigin(origins="*")
class ApiController {
 final UserRepository users; final ComplaintRepository complaints; final UpdateRepository updates; final ReviewRepository reviews; final DuplicateRepository duplicates;
 final BCryptPasswordEncoder encoder; final RestClient http;
 @Value("${ai.service.url}") String aiUrl;
 @Value("${app.token-secret}") String tokenSecret;
 ApiController(UserRepository u,ComplaintRepository c,UpdateRepository up,ReviewRepository r,DuplicateRepository d,BCryptPasswordEncoder e,RestClient h){users=u;complaints=c;updates=up;reviews=r;duplicates=d;encoder=e;http=h;}

 @PostConstruct void admin(){if(users.findByEmail("admin@college.edu").isEmpty())users.save(new User("System Administrator","admin@college.edu",encoder.encode(System.getenv().getOrDefault("ADMIN_PASSWORD","Admin@123")),"ADMIN"));}

 @PostMapping("/auth/register") ResponseEntity<?> register(@RequestBody Map<String,String> b){
  String name=trim(b.get("name")),email=trim(b.get("email")).toLowerCase(),pass=b.get("password");
  if(name.isBlank()||email.isBlank()||pass==null||pass.length()<8)return bad(400,"Enter your name, email and a password of at least 8 characters.");
  if(!pass.equals(b.get("confirmPassword")))return bad(400,"Passwords do not match.");
  if(users.findByEmail(email).isPresent())return bad(409,"An account with this email already exists.");
  User u=users.save(new User(name,email,encoder.encode(pass),"USER")); return ResponseEntity.status(201).body(Map.of("token",token(u),"user",userMap(u)));
 }
 @PostMapping("/auth/login") ResponseEntity<?> login(@RequestBody Map<String,String> b){User u=users.findByEmail(trim(b.get("email")).toLowerCase()).orElse(null);if(u==null||!encoder.matches(Objects.toString(b.get("password"),""),u.password))return bad(401,"Invalid email or password.");return ResponseEntity.ok(Map.of("token",token(u),"user",userMap(u)));}
 @GetMapping("/auth/me") ResponseEntity<?> me(@RequestHeader(value="Authorization",required=false) String a){User u=current(a);return u==null?bad(401,"Please sign in again."):ResponseEntity.ok(userMap(u));}

 @PostMapping("/complaints") ResponseEntity<?> submit(@RequestHeader(value="Authorization",required=false) String a,@RequestBody Map<String,String> b){
  User u=current(a);if(u==null)return bad(401,"Please sign in to submit a complaint.");
  String title=trim(b.get("title")),desc=trim(b.get("description")),loc=trim(b.get("location"));if(title.isBlank()||desc.isBlank())return bad(400,"Title and description are required.");
  Map<String,Object> analyzed;
  try { analyzed=http.post().uri(aiUrl+"/api/analyze").contentType(MediaType.APPLICATION_JSON).body(Map.of("title",title,"description",desc,"location",loc)).retrieve().body(Map.class); }
  catch(Exception ex){return bad(503,"AI analysis service is currently unavailable. Please try again.");}
  if(analyzed==null)return bad(503,"AI analysis service returned no result. Please try again.");
  Complaint c=new Complaint();c.user=u;c.title=title;c.description=desc;c.location=loc;c.qualityPassed=Boolean.TRUE.equals(analyzed.get("qualityPassed"));c.qualityMessage=Objects.toString(analyzed.get("qualityMessage"),"Complaint information is sufficient.");c.category=Objects.toString(analyzed.get("category"),"Other");c.urgency=Objects.toString(analyzed.get("urgency"),"MEDIUM");c.categoryConfidence=num(analyzed.get("categoryConfidence"),.5);c.urgencyConfidence=num(analyzed.get("urgencyConfidence"),.5);c.detectedLocation=Objects.toString(analyzed.get("detectedLocation"),loc);c.detectedTime=Objects.toString(analyzed.get("detectedTime"),"");c.aiReason=Objects.toString(analyzed.get("reason"),"AI analysis completed.");c.department=department(c.category);c.status="PENDING";c.priorityScore=score(c.urgency,c.category,c.description);c.priorityLevel=level(c.priorityScore);c=complaints.save(c);
  try {List<Complaint> today=complaints.findByCreatedAtBetweenAndIdNot(LocalDate.now().atStartOfDay(),LocalDate.now().plusDays(1).atStartOfDay(),c.id);Map<String,Object> dupe=http.post().uri(aiUrl+"/api/duplicate-check").contentType(MediaType.APPLICATION_JSON).body(Map.of("complaint",Map.of("id",c.id,"title",c.title,"description",c.description,"location",Objects.toString(c.location,"")),"existing",today.stream().map(x->Map.of("id",x.id,"title",x.title,"description",x.description,"location",Objects.toString(x.location,""))).toList())).retrieve().body(Map.class);if(dupe!=null&&Boolean.TRUE.equals(dupe.get("duplicateFound"))){c.duplicateComplaintId=Objects.toString(dupe.get("similarComplaintId"));c.similarityScore=num(dupe.get("similarityScore"),0);c=complaints.save(c);duplicates.save(new DuplicateRecord(c.id,parseLong(c.duplicateComplaintId),c.similarityScore));}}catch(Exception ignored){}
  updates.save(new ComplaintUpdate(c,"COMPLAINT_SUBMITTED","Complaint submitted by the student.",u.name));updates.save(new ComplaintUpdate(c,"AI_ANALYSIS_COMPLETED","Quality check, category and urgency analysis completed.","Qwen AI"));updates.save(new ComplaintUpdate(c,"DEPARTMENT_ASSIGNED","Suggested department: "+c.department,"System"));updates.save(new ComplaintUpdate(c,"PENDING","Complaint is awaiting department action.","System"));return ResponseEntity.status(201).body(Map.of("accepted",true,"qualityPassed",c.qualityPassed,"qualityMessage",c.qualityMessage,"complaint",complaintMap(c,true)));
 }
 @GetMapping("/complaints/my") ResponseEntity<?> mine(@RequestHeader(value="Authorization",required=false) String a){User u=current(a);if(u==null)return bad(401,"Please sign in.");return ResponseEntity.ok(complaints.findByUserIdOrderByCreatedAtDesc(u.id).stream().map(c->complaintMap(c,false)).toList());}
 @GetMapping("/complaints/{id}") ResponseEntity<?> detail(@RequestHeader(value="Authorization",required=false) String a,@PathVariable Long id){User u=current(a);if(u==null)return bad(401,"Please sign in.");Complaint c=complaints.findById(id).orElse(null);if(c==null)return bad(404,"Complaint not found.");if(!u.role.equals("ADMIN")&&!c.user.id.equals(u.id))return bad(403,"You cannot access this complaint.");return ResponseEntity.ok(complaintMap(c,true));}
 @GetMapping("/complaints/{id}/updates") ResponseEntity<?> complaintUpdates(@RequestHeader(value="Authorization",required=false) String a,@PathVariable Long id){User u=current(a);if(u==null)return bad(401,"Please sign in.");Complaint c=complaints.findById(id).orElse(null);if(c==null)return bad(404,"Complaint not found.");if(!u.role.equals("ADMIN")&&!c.user.id.equals(u.id))return bad(403,"You cannot access these updates.");return ResponseEntity.ok(updates.findByComplaintIdOrderByUpdatedAtAsc(id).stream().map(this::updateMap).toList());}
 @PostMapping("/complaints/{id}/review") ResponseEntity<?> review(@RequestHeader(value="Authorization",required=false) String a,@PathVariable Long id,@RequestBody Map<String,Object> b){User u=current(a);if(u==null)return bad(401,"Please sign in.");Complaint c=complaints.findById(id).orElse(null);if(c==null)return bad(404,"Complaint not found.");if(!c.user.id.equals(u.id))return bad(403,"You cannot review this complaint.");if(!c.status.equals("RESOLVED"))return bad(400,"Reviews are available after resolution.");if(reviews.findByComplaintId(id).isPresent())return bad(409,"A review has already been submitted.");int rating=(int)num(b.get("rating"),0);if(rating<1||rating>5)return bad(400,"Choose a rating from 1 to 5.");Review r=new Review();r.complaint=c;r.user=u;r.rating=rating;r.comment=Objects.toString(b.get("comment"),"");reviews.save(r);return ResponseEntity.status(201).body(Map.of("message","Review submitted."));}

 @GetMapping("/admin/dashboard") ResponseEntity<?> dashboard(@RequestHeader(value="Authorization",required=false) String a){if(!isAdmin(a))return bad(403,"Admin access required.");List<Complaint> all=complaints.findAll();return ResponseEntity.ok(Map.of("total",all.size(),"pending",all.stream().filter(c->c.status.equals("PENDING")).count(),"inProgress",all.stream().filter(c->c.status.equals("IN_PROGRESS")).count(),"resolved",all.stream().filter(c->c.status.equals("RESOLVED")).count()));}
 @GetMapping("/admin/complaints") ResponseEntity<?> all(@RequestHeader(value="Authorization",required=false) String a,@RequestParam(required=false) String category,@RequestParam(required=false) String urgency,@RequestParam(required=false) String priority,@RequestParam(required=false) String department,@RequestParam(required=false) String status,@RequestParam(required=false) String date,@RequestParam(required=false) String search){if(!isAdmin(a))return bad(403,"Admin access required.");return ResponseEntity.ok(complaints.findAll().stream().filter(c->blank(category)||c.category.equalsIgnoreCase(category)).filter(c->blank(urgency)||c.urgency.equalsIgnoreCase(urgency)).filter(c->blank(priority)||c.priorityLevel.equalsIgnoreCase(priority)).filter(c->blank(department)||c.department.equalsIgnoreCase(department)).filter(c->blank(status)||c.status.equalsIgnoreCase(status)).filter(c->blank(date)||c.createdAt.toLocalDate().toString().equals(date)).filter(c->blank(search)||(c.title+" "+c.user.name+" CMP-"+c.id).toLowerCase().contains(search.toLowerCase())).sorted(Comparator.comparing((Complaint c)->c.createdAt).reversed()).map(c->complaintMap(c,false)).toList());}
 @GetMapping("/admin/complaints/department/{dept}") ResponseEntity<?> dept(@RequestHeader(value="Authorization",required=false) String a,@PathVariable String dept){if(!isAdmin(a))return bad(403,"Admin access required.");return ResponseEntity.ok(complaints.findAll().stream().filter(c->c.department.equalsIgnoreCase(dept)).map(c->complaintMap(c,false)).toList());}
 @GetMapping("/admin/complaints/{id}") ResponseEntity<?> adminDetail(@RequestHeader(value="Authorization",required=false) String a,@PathVariable Long id){if(!isAdmin(a))return bad(403,"Admin access required.");Complaint c=complaints.findById(id).orElse(null);return c==null?bad(404,"Complaint not found."):ResponseEntity.ok(complaintMap(c,true));}
 @PutMapping("/admin/complaints/{id}") ResponseEntity<?> edit(@RequestHeader(value="Authorization",required=false) String a,@PathVariable Long id,@RequestBody Map<String,String> b){if(!isAdmin(a))return bad(403,"Admin access required.");Complaint c=complaints.findById(id).orElse(null);if(c==null)return bad(404,"Complaint not found.");if(b.containsKey("category"))c.category=b.get("category");if(b.containsKey("urgency"))c.urgency=b.get("urgency");if(b.containsKey("department"))c.department=b.get("department");if(b.containsKey("priorityScore")){c.priorityScore=Math.max(0,Math.min(100,(int)num(b.get("priorityScore"),c.priorityScore)));c.priorityLevel=level(c.priorityScore);}c.updatedAt=LocalDateTime.now();return ResponseEntity.ok(complaintMap(complaints.save(c),true));}
 @PutMapping("/admin/complaints/{id}/status") ResponseEntity<?> status(@RequestHeader(value="Authorization",required=false) String a,@PathVariable Long id,@RequestBody Map<String,String> b){User admin=current(a);if(admin==null||!admin.role.equals("ADMIN"))return bad(403,"Admin access required.");Complaint c=complaints.findById(id).orElse(null);if(c==null)return bad(404,"Complaint not found.");String s=Objects.toString(b.get("status"),"").toUpperCase();if(!Set.of("PENDING","IN_PROGRESS","RESOLVED","REJECTED").contains(s))return bad(400,"Invalid status.");c.status=s;c.updatedAt=LocalDateTime.now();complaints.save(c);updates.save(new ComplaintUpdate(c,s,Objects.toString(b.get("remark"),""),admin.name));return ResponseEntity.ok(complaintMap(c,true));}
 @PutMapping("/admin/complaints/{id}/department") ResponseEntity<?> department(@RequestHeader(value="Authorization",required=false) String a,@PathVariable Long id,@RequestBody Map<String,String> b){if(!isAdmin(a))return bad(403,"Admin access required.");Complaint c=complaints.findById(id).orElse(null);if(c==null)return bad(404,"Complaint not found.");c.department=b.get("department");c.updatedAt=LocalDateTime.now();return ResponseEntity.ok(complaintMap(complaints.save(c),true));}
 @DeleteMapping("/admin/complaints/{id}") ResponseEntity<?> delete(@RequestHeader(value="Authorization",required=false) String a,@PathVariable Long id){if(!isAdmin(a))return bad(403,"Admin access required.");Complaint c=complaints.findById(id).orElse(null);if(c==null)return bad(404,"Complaint not found.");updates.deleteAll(updates.findByComplaintIdOrderByUpdatedAtAsc(id));reviews.findByComplaintId(id).ifPresent(reviews::delete);duplicates.deleteByComplaintIdOrSimilarComplaintId(id,id);for(Complaint related:complaints.findByDuplicateComplaintId(id.toString())){related.duplicateComplaintId=null;related.similarityScore=0;complaints.save(related);}complaints.delete(c);return ResponseEntity.noContent().build();}

 Map<String,Object> complaintMap(Complaint c,boolean full){Map<String,Object> m=new LinkedHashMap<>();m.put("id",c.id);m.put("complaintCode","CMP-"+c.id);m.put("title",c.title);m.put("description",c.description);m.put("location",c.location);m.put("category",c.category);m.put("categoryConfidence",c.categoryConfidence);m.put("urgency",c.urgency);m.put("urgencyConfidence",c.urgencyConfidence);m.put("priorityScore",c.priorityScore);m.put("priorityLevel",c.priorityLevel);m.put("department",c.department);m.put("status",c.status);m.put("createdAt",c.createdAt);m.put("updatedAt",c.updatedAt);m.put("user",userMap(c.user));m.put("duplicateFound",c.duplicateComplaintId!=null);m.put("similarComplaintId",c.duplicateComplaintId==null?null:"CMP-"+c.duplicateComplaintId);m.put("similarityScore",c.similarityScore);if(full){m.put("qualityPassed",c.qualityPassed);m.put("qualityMessage",c.qualityMessage);m.put("missingInformation",c.missingInformation);m.put("detectedLocation",c.detectedLocation);m.put("detectedTime",c.detectedTime);m.put("aiReason",c.aiReason);m.put("updates",updates.findByComplaintIdOrderByUpdatedAtAsc(c.id).stream().map(this::updateMap).toList());m.put("review",reviews.findByComplaintId(c.id).map(r->Map.of("rating",r.rating,"comment",Objects.toString(r.comment,""))).orElse(null));}return m;}
 Map<String,Object> userMap(User u){return Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role);}
 Map<String,Object> updateMap(ComplaintUpdate x){return Map.of("status",x.status,"remark",Objects.toString(x.remark,""),"updatedBy",Objects.toString(x.updatedBy,""),"updatedAt",x.updatedAt);}
 int score(String urgency,String category,String text){int urg=switch(urgency){case "LOW"->20;case "MEDIUM"->40;case "HIGH"->70;default->90;};int cat=switch(category){case "Security","Electricity"->10;case "Water"->8;case "IT"->7;case "Infrastructure"->6;case "Cleanliness"->5;default->3;};int impact=text.toLowerCase().matches(".*\\b(all students|entire|many students|campus-wide|multiple|students cannot)\\b.*")?90:50;return Math.max(0,Math.min(100,Math.round((float)(urg*.50+impact*.25+cat*1.5+20*.10))));}
 String level(int s){return s>=80?"CRITICAL":s>=60?"HIGH":s>=40?"MEDIUM":"LOW";}
 String department(String c){return switch(c){case "IT"->"IT Department";case "Infrastructure"->"Maintenance Department";case "Electricity"->"Electrical Department";case "Water"->"Plumbing Department";case "Cleanliness"->"Housekeeping Department";case "Security"->"Security Department";default->"General Administration";};}
 User current(String auth){try{String[] p=Objects.requireNonNull(auth).replace("Bearer ","").split("\\.");String data=new String(Base64.getUrlDecoder().decode(p[0]),StandardCharsets.UTF_8);if(!sign(p[0]).equals(p[1]))return null;return users.findById(Long.parseLong(data.split("\\|")[0])).orElse(null);}catch(Exception e){return null;}}
 String token(User u){String raw=Base64.getUrlEncoder().withoutPadding().encodeToString((u.id+"|"+u.role).getBytes(StandardCharsets.UTF_8));return raw+"."+sign(raw);}
 String sign(String value){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(tokenSecret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 boolean isAdmin(String a){User u=current(a);return u!=null&&u.role.equals("ADMIN");} ResponseEntity<Map<String,String>> bad(int code,String message){return ResponseEntity.status(code).body(Map.of("message",message));}
 String trim(String s){return Objects.toString(s,"").trim();} boolean blank(String s){return s==null||s.isBlank();} double num(Object o,double d){try{return Double.parseDouble(o.toString());}catch(Exception e){return d;}} Long parseLong(String s){try{return Long.parseLong(s);}catch(Exception e){return null;}}
}
